class Base {
    public:
        virtual void virtualFunc();  // Declares a virtual function; compiler adds an entry in the vtable
        int dataMember;  // Non-virtual member; follows the vptr in memory layout
};

class Derived : public Base {
    public:
        void virtualFunc() override;  // Overrides the virtual function; compiler updates the vtable entry for Derived
};

// Implementation notes: The 'virtual' keyword triggers vtable generation. The vptr is implicitly added by the compiler, typically as the first member, affecting object size and alignment. Overriding a virtual function updates the vtable pointer for that slot in derived classes.
